import { useEffect, useState } from 'react';
import { AlarmClock, RefreshCw } from 'lucide-react';
import { api } from '../lib/api';
import NewHereHint from './NewHereHint';
import { EmptyState } from './EmptyState';

/**
 * Early-departures leaderboard (T122).
 *
 * Which routes leave stops >= 2 minutes ahead of schedule most often —
 * computed entirely from the published 250k-row Zenodo sample (DOI
 * 10.5281/zenodo.22820448), so every number here a reader can reproduce
 * from the deposit alone. An early bus is a missed bus for a timetable
 * rider: the schedule promised time the route didn't need, and the slack
 * comes out of the rider's side of the transaction.
 *
 * Evidentiary basis: `measured` — but with a structural caveat the panel
 * keeps visible: the table ranks the *rate*, not the *cause* (schedule
 * slack, running-time variability, or dispatch practice cannot be
 * distinguished from the sample).
 */

interface RouteRow {
  route: string;
  n: number;
  early_share: number;
}

interface LeaderboardResponse {
  available?: boolean;
  /** Why the leaderboard is unavailable (missing public sample, etc.). */
  reason?: string;
  generated_at: string;
  basis: {
    source: string;
    n: number;
    window: string;
    definition: string;
  };
  routes: RouteRow[];
  network: RouteRow;
  /** Routes below the n>=1000 ranking cutoff (list of route ids). */
  small_n: string[];
}

const PCT = (x: number) => `${(x * 100).toFixed(1)}%`;

function Bar({ share, highlight }: { share: number; highlight: boolean }) {
  return (
    <div className="h-2 w-full rounded bg-border">
      <div
        className={`h-2 rounded ${highlight ? 'bg-rose-500' : 'bg-text-muted/50'}`}
        style={{ width: `${Math.min(100, share * 100)}%` }}
      />
    </div>
  );
}

export default function EarlyDeparturesPanel() {
  const [data, setData] = useState<LeaderboardResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const d = await api.publicEarlyDepartures();
      setData(d);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, []);

  const worst = data?.routes[0];
  const best = data?.routes.length ? data.routes[data.routes.length - 1] : undefined;

  return (
    <div className="space-y-3">
      <div className="flex items-start justify-between">
        <div>
          <h2 className="flex items-center gap-2 text-lg font-semibold text-text-primary">
            <AlarmClock className="h-5 w-5 text-rose-500" aria-hidden />
            Early departures
          </h2>
          <p className="text-sm text-text-muted">
            Share of departures leaving {'>'}= 2 min ahead of schedule, by route — a
            timetable rider's "the bus already left" failure mode.
          </p>
        </div>
        <button
          onClick={() => void load()}
          className="rounded p-1 text-text-muted hover:text-text-primary"
          aria-label="Reload"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {loading && (
        <div role="status" aria-live="polite" className="p-6 text-sm text-text-muted">
          Computing the leaderboard…
        </div>
      )}
      {error && (
        <div
          role="alert"
          className="rounded-xl border border-rose-300 bg-rose-50 p-3 text-sm text-rose-700"
        >
          {error}
        </div>
      )}
      {!error && data?.available === false && (
        <div
          role="status"
          className="rounded-xl border border-amber-300 bg-amber-50 p-3 text-sm text-amber-800"
        >
          {data.reason ?? 'Leaderboard data not available in this environment.'}
        </div>
      )}

      {data && (
        <>
          <div className="mt-3">
            <NewHereHint text="The worst route here leaves early on 2 of every 5 departures — over four times the best large-n route. The whole table is computed only from the published public sample, so every number can be reproduced from the dataset itself." />
          </div>

          {/* The headline contrast */}
          {worst && best && (
            <div className="rounded-xl border border-border bg-card/50 p-3 text-sm text-text-primary">
              <span className="font-semibold">Route {worst.route}</span> leaves ≥2 min
              early on <span className="font-semibold text-rose-600">{PCT(worst.early_share)}</span> of
              departures (n={worst.n.toLocaleString()}) — more than four times route {best.route}'s{' '}
              <span className="font-semibold text-emerald-600">{PCT(best.early_share)}</span>.{' '}
              This is a <em>schedule-design</em> signature, not random noise: the
              timetable books running time the route doesn't need, and the slack
              comes out early.
            </div>
          )}

          {/* The ranked table */}
          <div className="overflow-hidden rounded-xl border border-border">
            <table className="w-full text-sm">
              <thead className="bg-card/70 text-left text-xs uppercase tracking-wide text-text-muted">
                <tr>
                  <th className="px-3 py-2">Route</th>
                  <th className="px-3 py-2">n</th>
                  <th className="w-1/2 px-3 py-2">Early-departure share</th>
                </tr>
              </thead>
              <tbody>
                {data.routes.map((r, i) => (
                  <tr
                    key={r.route}
                    className={`border-t border-border ${i === 0 ? 'font-semibold' : ''}`}
                  >
                    <td className="px-3 py-1.5 text-text-primary">{r.route}</td>
                    <td className="px-3 py-1.5 text-text-muted">{r.n.toLocaleString()}</td>
                    <td className="px-3 py-1.5">
                      <div className="flex items-center gap-2">
                        <Bar share={r.early_share} highlight={i === 0} />
                        <span className={`w-14 text-right tabular-nums ${i === 0 ? 'text-rose-600' : 'text-text-primary'}`}>
                          {PCT(r.early_share)}
                        </span>
                      </div>
                    </td>
                  </tr>
                ))}
                <tr className="border-t border-border bg-card/70">
                  <td className="px-3 py-1.5 italic text-text-muted">network</td>
                  <td className="px-3 py-1.5 text-text-muted">{data.network.n.toLocaleString()}</td>
                  <td className="px-3 py-1.5">
                    <div className="flex items-center gap-2">
                      <Bar share={data.network.early_share} highlight={false} />
                      <span className="w-14 text-right tabular-nums text-text-primary">
                        {PCT(data.network.early_share)}
                      </span>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          {/* Honesty notes */}
          <div className="rounded-xl border border-amber-300 bg-amber-50 p-3 text-xs text-amber-800">
            <p>
              <strong>Basis:</strong> {data.basis.source}, {data.basis.n.toLocaleString()} rows ({data.basis.window});
              definition: {data.basis.definition}. Routes with fewer than 1,000
              observations are excluded from the ranking
              {data.small_n?.length ? ` (${data.small_n.slice(0, 8).join(', ')}${data.small_n.length > 8 ? '…' : ''})` : ''}.
            </p>
            <p className="mt-1">
              <strong>What this can't say:</strong> the table ranks the rate, not the
              cause — schedule slack, running-time variability, and terminal
              dispatch practice are indistinguishable in this dataset, and no
              operator misconduct is alleged. Future re-cuts of the deposit
              (v1.1.0+) will shift these numbers slightly; cite with the dataset
              version.
            </p>
          </div>
        </>
      )}

      {!loading && !error && !data && <EmptyState reason="The early-departures endpoint returned nothing." onRetry={() => void load()} />}
    </div>
  );
}
